-- Vanshawali 360 D1 schema v1. Private family data: NEVER expose without authentication and tenant authorization.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS families (id TEXT PRIMARY KEY, name TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS family_users (id TEXT PRIMARY KEY, family_id TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE, auth_subject TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('owner','admin','editor','viewer')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(family_id,auth_subject));
CREATE TABLE IF NOT EXISTS households (id TEXT PRIMARY KEY, family_id TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE, title TEXT NOT NULL, ward TEXT, address TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(family_id,id));
CREATE TABLE IF NOT EXISTS members (id TEXT PRIMARY KEY, family_id TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE, household_id TEXT, full_name TEXT NOT NULL, gender TEXT CHECK(gender IN ('male','female','other','unknown')), birth_date TEXT, death_date TEXT, notes TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(family_id,id), FOREIGN KEY(family_id,household_id) REFERENCES households(family_id,id));
CREATE TABLE IF NOT EXISTS relationships (id TEXT PRIMARY KEY, family_id TEXT NOT NULL, member_id TEXT NOT NULL, related_member_id TEXT NOT NULL, relationship_type TEXT NOT NULL CHECK(relationship_type IN ('parent','spouse','sibling','other')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK(member_id<>related_member_id), UNIQUE(family_id,member_id,related_member_id,relationship_type), FOREIGN KEY(family_id,member_id) REFERENCES members(family_id,id) ON DELETE CASCADE, FOREIGN KEY(family_id,related_member_id) REFERENCES members(family_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS events (id TEXT PRIMARY KEY, family_id TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE, title TEXT NOT NULL, event_type TEXT NOT NULL, starts_at TEXT, location TEXT, description TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(family_id,id));
CREATE TABLE IF NOT EXISTS invitations (id TEXT PRIMARY KEY, family_id TEXT NOT NULL, event_id TEXT NOT NULL, template TEXT NOT NULL, content_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(family_id,event_id) REFERENCES events(family_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS media_files (id TEXT PRIMARY KEY, family_id TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE, member_id TEXT, object_key TEXT NOT NULL UNIQUE, original_filename TEXT NOT NULL, content_type TEXT NOT NULL, size_bytes INTEGER NOT NULL CHECK(size_bytes>=0), visibility TEXT NOT NULL DEFAULT 'private' CHECK(visibility IN ('private','family')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(family_id,member_id) REFERENCES members(family_id,id));
CREATE TABLE IF NOT EXISTS passbook_entries (id TEXT PRIMARY KEY, family_id TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE, member_id TEXT, amount_paisa INTEGER NOT NULL CHECK(amount_paisa>=0), entry_type TEXT NOT NULL CHECK(entry_type IN ('credit','debit')), description TEXT NOT NULL, occurred_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(family_id,member_id) REFERENCES members(family_id,id));
CREATE TABLE IF NOT EXISTS audit_logs (id TEXT PRIMARY KEY, family_id TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE, actor_subject TEXT NOT NULL, action TEXT NOT NULL, resource_type TEXT NOT NULL, resource_id TEXT, occurred_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_members_family_name ON members(family_id,full_name);
CREATE INDEX IF NOT EXISTS idx_members_family_household ON members(family_id,household_id);
CREATE INDEX IF NOT EXISTS idx_relationships_from ON relationships(family_id,member_id);
CREATE INDEX IF NOT EXISTS idx_relationships_to ON relationships(family_id,related_member_id);
CREATE INDEX IF NOT EXISTS idx_events_by_family_date ON events(family_id,starts_at);
CREATE INDEX IF NOT EXISTS idx_media_family_member ON media_files(family_id,member_id);
CREATE INDEX IF NOT EXISTS idx_passbook_family_date ON passbook_entries(family_id,occurred_at);
CREATE INDEX IF NOT EXISTS idx_audit_family_date ON audit_logs(family_id,occurred_at);
